type Handlers struct {
	db       *sql.DB
	hub      *Hub
	d3bitURL string
	distFS   fs.FS

	userCacheMu sync.RWMutex
	userCache   map[string]*cachedUser
}

type D3bitUser struct {
	ID          string `json:"id"`
	Email       string `json:"email"`
	Name        string `json:"name"`
	AvatarURL   string `json:"avatar_url"`
	IsAnon      bool   `json:"is_anon"`
	DisplayName string `json:"display_name"`
	Color       string `json:"color"`
	Username    string `json:"username"`
}

func (h *Handlers) resolveD3bitUser(r *http.Request) *D3bitUser {
	if h.d3bitURL == "" {
		return nil
	}
	cookie, err := r.Cookie("d3_session")
	if err != nil || cookie.Value == "" {
		return nil
	}

	// Check cache (60s TTL)
	h.userCacheMu.RLock()
	if cached, ok := h.userCache[cookie.Value]; ok && time.Now().Before(cached.expiresAt) {
		h.userCacheMu.RUnlock()
		return cached.user
	}
	h.userCacheMu.RUnlock()

	req, err := http.NewRequestWithContext(r.Context(), "GET", h.d3bitURL+"/auth/me", nil)
	if err != nil {
		return nil
	}
	req.AddCookie(cookie)
	resp, err := http.DefaultClient.Do(req)
	if err != nil || resp.StatusCode != 200 {
		return nil
	}
	defer resp.Body.Close()
	var envelope struct {
		Data D3bitUser `json:"data"`
	}
	if json.NewDecoder(resp.Body).Decode(&envelope) != nil {
		return nil
	}
	if envelope.Data.ID == "" {
		return nil
	}

	// Store in cache
	h.userCacheMu.Lock()
	h.userCache[cookie.Value] = &cachedUser{user: &envelope.Data, expiresAt: time.Now().Add(60 * time.Second)}
	h.userCacheMu.Unlock()

	return &envelope.Data
}

func (h *Handlers) getUserAndRole(r *http.Request, slug string) (*D3bitUser, string) {
	user := h.resolveD3bitUser(r)
	if user == nil {
		return nil, RoleDefault
	}
	return user, GetMemberRole(h.db, slug, user.ID)
}

