import { defineStore } from 'pinia'
import { ref } from 'vue'
import { apiPost, apiPatch } from '@/composables/useApi'
import type { User } from '@/types'

export const useAuthStore = defineStore('auth', () => {
  const user = ref<User | null>(null)
  const loading = ref(true)
  const isSuperadmin = ref(false)

  async function fetchMe() {
    loading.value = true
    try {
      const res = await fetch('/d3bit/auth/me', { credentials: 'include' })
      if (!res.ok) {
        user.value = null
        return
      }
      const json = await res.json()
      user.value = json.data ?? json
    } catch {
      user.value = null
    } finally {
      loading.value = false
    }
  }

  async function createAnon() {
    try {
      const res = await fetch('/d3bit/auth/anon', { method: 'POST', credentials: 'include' })
      if (!res.ok) return
      const json = await res.json()
      user.value = json.data?.user ?? json.user ?? json.data ?? json
    } catch {
      // ignore
    }
  }

  async function ensureSession() {
    await fetchMe()
    if (!user.value) {
      await createAnon()
    }
    // Check superadmin status
    if (user.value && !user.value.is_anon) {
      try {
        const res = await fetch('/api/admin/check', { credentials: 'include' })
        if (res.ok) {
          const data = await res.json()
          isSuperadmin.value = data.is_superadmin === true
        }
      } catch { /* ignore */ }
    }
  }

  async function login(email: string): Promise<{ ok?: boolean; magic_link?: string; error?: string }> {
    try {
      const callback = window.location.origin + '/auth/callback'
      return await apiPost<{ ok: boolean; magic_link?: string }>('/d3bit/auth/login', { email, redirect: callback })
    } catch (e: any) {
      return { error: e.message || 'Something went wrong' }
    }
  }

  async function logout() {
    try {
      await apiPost('/d3bit/auth/logout')
    } catch {
      // ignore
    }
    user.value = null
  }

  async function updateProfile(updates: Partial<Pick<User, 'display_name' | 'username' | 'color' | 'avatar_url'>>) {
    const result = await apiPatch<User>('/d3bit/auth/me', updates)
    user.value = result
    return result
  }

  async function saveProfileAvatar() {
    const result = await apiPost<User>('/api/profile-canvas/avatar')
    user.value = result
    return result
  }

  return { user, loading, isSuperadmin, fetchMe, createAnon, ensureSession, login, logout, updateProfile, saveProfileAvatar }
})
