// Everything below shapes room state for a template. Keeping the arithmetic
// here rather than in the markup means the templates stay readable and the
// logic stays testable.

type homeView struct {
	User         *D3bitUser
	Lobbies      []lobbyView
	PlayerCounts []int
	GoogleURL    string
